local KTool = CS.Engine.Lib.KTool

--- from: Assets/BundleResources/Prefabs/Activity/ActivityCakeShopDialog113003.prefab > name: ActivityCakeShopDialog113003
---@class ActivityCakeShopDialog
---@field Env                           	ActivityCakeShopDialog                  
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field BtnEntrance                   	UnityEngine.RectTransform               	@ 0    
---@field StateText                     	UnityEngine.UI.Text                     	@ 1    
---@field ImgTitleName                  	Engine.UI.WebRawImage                   	@ 2    
