---@field Open                          	UnityEngine.RectTransform               	@ 4    
---@field Close                         	UnityEngine.RectTransform               	@ 5    
local ActivityCakeShopDialog = Class('ActivityCakeShopDialog')
local ActivityCakeUtils = import('Game.UI.ActivityCakeShopDialog.ActivityCakeUtils')

function ActivityCakeShopDialog:__init()
    self.activityData = nil
end

function ActivityCakeShopDialog:__delete()
    self.activityData = nil
end

function ActivityCakeShopDialog:Awake()
    self:AddUIClick()
end

function ActivityCakeShopDialog:AddUIClick()
    SetButtonAction(self.BtnEntrance.gameObject,Bind(self,self.OnBtnEnterClick))
end

function ActivityCakeShopDialog:OnBtnEnterClick()
    local isUnlock = self:IsUnLock()
    if not isUnlock then
        GameUtils.Toast(self:GetUnLockDesc())
        return
    end
    CS.Engine.UI.UIModule.OpenDialog({ id = self.activityData.moduleId, parameters = { activityData = self.activityData}}, { { id = Constants.UITypeIds.UIActivityMainDialog } })
end

function ActivityCakeShopDialog:IsUnLock()
    local isUnlock = GameUtils.IsUnlockedSingle(self.activityData.unlock[1].targetType, self.activityData.unlock[1].targetNum, self.activityData.unlock[1].targetId)
    return isUnlock
end

function ActivityCakeShopDialog:GetUnLockDesc()
    local unLockDesc = GameUtils.GetUnlockDescr(self.activityData.unlock[1].targetType, self.activityData.unlock[1].targetNum, self.activityData.unlock[1].targetId)
    return unLockDesc
end

function ActivityCakeShopDialog:Refresh(data)
    self.activityData = data
    ActivityCakeUtils.GetActivityCakeMgr():SaveActivityData(self.activityData)
    self:SetTitle()
    self:SetTimeShow()
    self:RefreshLockState()
end

function ActivityCakeShopDialog:RefreshLockState()
    local isUnlock = self:IsUnLock()
    KTool.SetActive(self.Open.gameObject,isUnlock)
    KTool.SetActive(self.Close.gameObject,not isUnlock)
end

function ActivityCakeShopDialog:SetTimeShow()
    --region 时间
    local startTime =  self.activityData.startTime
    local closeTime =  self.activityData.closeTime
    local ActivityUtils         = import("Game.Activity.ActivityUtils")
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(startTime, closeTime))

    local endTimeLeave = self.activityData.endTime - os.time()
    CfUtils.FillText(self.TextTime2,CfUtils.GetTimeHMS(endTimeLeave))

    -- CfUtils.FillText(self.TextTime, os.date("%Y.%m.%d", startTime).."-"..os.date("%Y.%m.%d  %H:%M", closeTime))
end

function ActivityCakeShopDialog:SetTitle()
    CfUtils.FillText(self.StateText,self.activityData.detail)

    local titleImgUrl = checkString(self.activityData.titleImage)
    if string.len(titleImgUrl) > 0 then
        CfUtils.FillWebRawImage(self.ImgTitleName, titleImgUrl)
    end
end

function ActivityCakeShopDialog:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ActivityCakeShopDialog